// ---------------------------------------------------------------------------
// Finding formatting (finding-parser.py::format_findings, markdown branch)
// ---------------------------------------------------------------------------

/** Render findings as the markdown block used inside reviewer/fixer prompts. */
function formatFindings(findings) {
  if (!findings.length) {
    return "No findings.";
  }

  const lines = [];
  for (const f of findings) {
    const fid = f.id ?? "?";
    const title = f.title ?? "Untitled";
    const severity = f.severity ?? "?";
    const requirement = f.requirement ?? "";
    const findingText = f.finding ?? "";
    const recommendation = f.recommendation ?? "";

    const evidenceRaw = f.evidence ?? "";
    let evidence;
    if (Array.isArray(evidenceRaw)) {
      evidence = evidenceRaw;
    } else if (evidenceRaw) {
      evidence = [evidenceRaw];
    } else {
      evidence = [];
    }
    const sources = "sources" in f ? f.sources : [f.source ?? ""];

    lines.push(`### ${fid}: ${title}`);
    lines.push(`**Severity:** ${severity}`);
    lines.push(`**Requirement:** ${requirement}`);
    lines.push(`**Finding:** ${findingText}`);
    lines.push(`**Recommendation:** ${recommendation}`);

    if (evidence.length) {
      const evidenceStr = evidence.filter((e) => e).map((e) => String(e)).join(", ");
      if (evidenceStr) {
        lines.push(`**Evidence:** ${evidenceStr}`);
      }
    }

    if (Array.isArray(sources) && sources.length) {
      lines.push(`**Sources:** ${sources.map((s) => String(s)).join(", ")}`);
    } else if (sources) {
      lines.push(`**Sources:** ${sources}`);
    }

    lines.push("");
  }

  return lines.join("\n").replace(/\s+$/, "");
}

// ---------------------------------------------------------------------------
// Reviewer prompt (finding-parser.py::get_reviewer_prompt)
// ---------------------------------------------------------------------------

/**
 * Build a reviewer prompt. The workflow supplies file content directly.
 * Round 2+ (roundNum > 1) appends prior findings, applied resolutions, and
 * verification instructions.
 */
function buildReviewerPrompt(agent, {
  artifactContent,
  requirementsContent,
  testSummary = "No test results available.",
  roundNum = 1,
  priorFindings = [],
  priorResolutions = [],
} = {}) {
  const reviewerName = agent.name;
  const reviewLens = agent.review_lens;

  const parts = [
    `You are a ${reviewerName} reviewing an artifact.`,
    "",
    `Your review lens: ${reviewLens}`,
    "",
    "## Artifact",
    "",
    artifactContent,
    "",
    "## Requirements",
    "",
    requirementsContent,
    "",
    "## Test Results",
    "",
    testSummary,
  ];

  if (roundNum > 1) {
    if (priorFindings.length) {
      parts.push(
        "",
        `## Prior Round Findings (Round ${roundNum - 1})`,
        "",
        formatFindings(priorFindings),
      );
    }

    if (priorResolutions.length) {
      const resLines = [];
      for (const res of priorResolutions) {
        const fid = res.finding_id ?? "?";
        const status = res.status ?? "?";
        const desc = res.description ?? "";
        const evidence = res.evidence ?? "";
        resLines.push(`- **${fid}**: ${status} -- ${desc}`);
        if (evidence) {
          resLines.push(`  Evidence: ${evidence}`);
        }
      }
      parts.push("", "## Fix Resolutions Applied", "", resLines.join("\n"));
    }

    parts.push(
      "",
      "## Verification Instructions",
      "",
      `The artifact content above is the POST-FIX version (after round ${roundNum - 1} fixes). ` +
        "For each fix resolution listed above, navigate to the cited evidence location " +
        "in the artifact and verify the fix is correct. Also check for NEW issues " +
        "introduced by the fixes — regressions, broken logic, incomplete changes.",
    );
  }

  const outputInstructions = REVIEWER_OUTPUT_INSTRUCTIONS.replace(
    "{reviewer_name}",
    reviewerName,
  );
  parts.push(
    "",
    "## Instructions",
    "",
    `Review the artifact against the requirements through your lens of ${reviewLens}.`,
    "",
    outputInstructions,
  );

  return parts.join("\n");
}

// ---------------------------------------------------------------------------
// Fixer prompt (finding-parser.py::get_fixer_prompt)
// ---------------------------------------------------------------------------

/** Build the fixer prompt listing every finding that must be resolved. */
function buildFixerPrompt({
  artifactContent,
  requirementsContent,
  testSummary = "",
  findings = [],
} = {}) {
  const findingsText = formatFindings(findings);

  return `You are a fixer agent. Your job is to fix ALL findings from the review.

## Artifact

${artifactContent}

## Requirements

${requirementsContent}

## Test Results

${testSummary}

## Findings to Fix (ALL must be addressed)

${findingsText}

## Instructions

Fix EVERY finding listed above. Every single one, regardless of severity (P0 through P3).

For each finding, produce a resolution with these fields:
- finding_id: the ID of the finding being resolved (e.g., P0-001)
- status: MUST be "FIXED" with evidence of the fix. No WONTFIX, DEFERRED, or OUT_OF_SCOPE.
- evidence: what changed and where (file:line for code, section:quote for content)
- description: brief explanation of the fix

If a finding is genuinely unfixable (requires external dependency, architectural constraint, or user decision), set status to "ESCALATED" with justification.

Output a JSON array of resolution objects. No other text.`;
}

// ===== inlined from workflow-helpers.mjs (generated; edit workflow-helpers.mjs, then rebuild) =====
// Orchestration-only helpers for review-loop.workflow.js.
//
// These are NOT part of the Python-oracle adjudication contract (they have no
// Python equivalent), so they live outside adjudication.mjs and are inlined
// into the generated workflow separately. Pure functions; unit-tested by
// workflow-helpers.test.mjs.

/**
 * Make finding IDs unique within a synthesized set.
 *
 * Reviewers number their own findings independently (P0-001, P0-002, ...), so
 * two distinct findings from two reviewers routinely collide on the same id.
 * Dedup merges by *title*, not id, so collisions survive synthesis — which
 * breaks the id-keyed fix-ALL gate (checkFixCompleteness) and tempts the fixer
 * to invent disambiguated ids that then match nothing. This suffixes each
 * collision deterministically (`P0-001`, `P0-001-2`, `P0-001-3`, …), preserving
 * order and leaving already-unique ids untouched.
 */
function ensureUniqueIds(findings) {
  const counts = new Map();
  return findings.map((f) => {
    const id = String(f.id ?? "");
    const n = (counts.get(id) ?? 0) + 1;
    counts.set(id, n);
    return n === 1 ? f : { ...f, id: `${id}-${n}` };
  });
}

// ---------------------------------------------------------------------------
// Adjudicated-findings ledger
//
// Reviewers are clean-context BY DESIGN — fresh eyes catch bugs a primed
// reviewer rationalizes away. But before this, only round N-1's findings reached
// round N, so by round 3 the earlier rounds were simply gone. A production run
// (2026-08-01) spent 5 rounds re-litigating geometry round 1 had already settled
// while each new fix introduced a new P1: "clean context" had degraded into
// amnesia.
//
// The ledger is the narrow fix: a CUMULATIVE record of findings whose resolution
// is SETTLED, carried into every later round. It deliberately excludes anything
// open — telling a fresh reviewer "the previous round thinks X is broken" primes
// them to confirm X, which is exactly the bias clean context exists to avoid.
// ---------------------------------------------------------------------------

/** Normalized title — the identity key for a finding across rounds. */
function ledgerKey(x) {
  return String(x.title ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

/**
 * Decide which of a round's findings are SETTLED and belong in the ledger.
 *
 * A finding is admitted only when BOTH hold:
 *   1. the fixer returned a `FIXED` resolution for its id (an `ESCALATED` one is
 *      an open question, not a settled decision), and
 *   2. the NEXT round's reviewers did not re-raise the same normalized title —
 *      i.e. the fix demonstrably held. A claimed-but-contradicted fix must never
 *      be labelled "do not re-litigate".
 *
 * `nextRoundFindings` is what makes (2) checkable, so a round is adjudicated one
 * round LATE — round r's entries are admitted when round r+1's findings are known.
 *
 * `resolution` is currently always "fixed" — the only adjudication the engine can
 * make automatically. The field is a string (not a boolean) so a future
 * dismissed-with-evidence path (a reviewer finding ruled invalid rather than
 * repaired) can emit "dismissed" without changing the ledger shape or renderer.
 *
 * @returns ledger entries: {id, round, severity, title, summary, file, resolution, resolved_by, evidence}
 */
function adjudicateRound({
  round,
  findings = [],
  resolutions = [],
  nextRoundFindings = [],
}) {
  const fixedById = new Map();
  for (const res of resolutions) {
    if (String(res?.status ?? "").toUpperCase() === "FIXED") {
      fixedById.set(String(res.finding_id ?? ""), res);
    }
  }

  const stillLive = new Set(nextRoundFindings.map(ledgerKey));

  const entries = [];
  for (const f of findings) {
    const res = fixedById.get(String(f.id ?? ""));
    if (!res) continue; // open, or escalated → not settled
    if (stillLive.has(ledgerKey(f))) continue; // the fix did not hold
    entries.push({
      id: String(f.id ?? ""),
      round,
      severity: String(f.severity ?? ""),
      title: String(f.title ?? ""),
      summary: String(res.description ?? f.finding ?? ""),
      file: String(f.evidence ?? res.evidence ?? ""),
      resolution: "fixed",
      resolved_by: `round ${round} fixer`,
      evidence: String(res.evidence ?? ""),
    });
  }
  return entries;
}

/**
 * Accumulate new entries onto the running ledger, keyed by normalized title so
 * the same issue adjudicated twice collapses to its NEWEST adjudication rather
 * than appearing twice. Order follows first appearance; a replaced entry keeps
 * its original slot so the ledger reads chronologically.
 */
function mergeLedger(ledger = [], entries = []) {
  const out = [...ledger];
  const indexByKey = new Map(out.map((e, i) => [ledgerKey(e), i]));
  for (const e of entries) {
    const key = ledgerKey(e);
    const at = indexByKey.get(key);
    if (at === undefined) {
      indexByKey.set(key, out.length);
      out.push(e);
    } else {
      out[at] = e;
    }
  }
  return out;
}

/**
 * Render the ledger as the prompt section injected into later rounds. Returns
 * "" for an empty ledger so callers never emit a dead heading.
 */
function renderLedger(ledger = []) {
  if (!ledger.length) return "";

  const lines = [
    "## ADJUDICATED-FINDINGS LEDGER",
    "",
    "These findings were raised in PRIOR rounds and are already adjudicated —",
    "each was fixed, and a later round confirmed the fix held. Treat them as",
    "settled:",
    "",
    "- **Do NOT re-litigate them.** Re-raising a settled finding as though it were",
    "  new is the failure mode this ledger exists to prevent.",
    "- **DO verify the listed fixes actually held** at the cited evidence location.",
    "- **If a listed fix has regressed or was undone, report it as a NEW finding**",
    "  with normal severity — a regression is a real bug, not a re-litigation.",
    "- This ledger is not a checklist of everything wrong with the artifact. Issues",
    "  it does not mention are still fully in scope for your review.",
    "",
  ];

  for (const e of ledger) {
    lines.push(`### ${e.id} (round ${e.round}, ${e.severity}): ${e.title}`);
    lines.push(`**Resolution:** ${e.resolution} — ${e.resolved_by}`);
    if (e.summary) lines.push(`**What was done:** ${e.summary}`);
    if (e.evidence) lines.push(`**Evidence:** ${e.evidence}`);
    else if (e.file) lines.push(`**Location:** ${e.file}`);
    lines.push("");
  }

  return lines.join("\n").replace(/\s+$/, "");
}

// ---------------------------------------------------------------------------
// Reviewer attestation + quorum (#81 / this repo #43)
//
// A review round is EVIDENCE only if the panel that was asked for actually
// reported. Before this, `reviews.filter(Boolean)` dropped every reviewer that
// failed to return, so a dead reviewer and a reviewer that found nothing were
// indistinguishable — and an all-dead round yielded zero findings, which the
// termination rule read as CONVERGED. That false GREEN shipped twice on record:
// 29 of 32 review agents died on a usage limit and the loop returned
// `converged:true` over a broken artifact (2026-08), and both reviewers died on
// `Login expired` while the surviving spot-fixer wrote a test that PINNED a known
// defect, all under a green verdict (Quark, 2026-09-02).
//
// So the count is never dropped: every requested reviewer is attested as returned
// or missing-with-a-reason, and the quorum decides whether the round counts.
// ---------------------------------------------------------------------------

/** A reviewer that produced nothing at all — the shape `filter(Boolean)` ate. */
const REVIEWER_NO_RESULT = "returned no result (agent produced no output)";
/** A reviewer that answered with something that is not a findings list. */
const REVIEWER_MALFORMED = "returned a malformed result (no findings array)";
/** A death whose cause the runtime did not name. */
const REVIEWER_UNKNOWN_REASON = "failed for an unnamed reason";

// Reasons come from agent runtimes and can be long or multi-line; the verdict has
// to stay one readable line, so normalize and cap them.
function cleanReason(reason) {
  const s = String(reason ?? "").replace(/\s+/g, " ").trim();
  if (!s) return REVIEWER_UNKNOWN_REASON;
  return s.length > 240 ? `${s.slice(0, 237)}...` : s;
}

/**
 * How many reviewers must actually report for a round to count as evidence.
 *
 * A majority of the panel, with a floor of 2 (or the whole panel when only one
 * was asked for, as in a proportional verifier round). Majority — not a fixed
 * floor — is what makes the 29-of-32 shape INVALID: three survivors clear any
 * constant floor while 90% of the lenses are silent.
 */
function reviewerQuorum(requested) {
  const n = Math.max(0, Math.trunc(Number(requested) || 0));
  if (n === 0) return 0;
  return Math.max(Math.min(2, n), Math.ceil(n / 2));
}

/**
 * Attest one round's reviewer panel.
 *
 * @param settled per-reviewer results in request order, each
 *   `{ name, ok: true, value }` or `{ name, ok: false, reason }`. The caller
 *   settles them (catching rejections) so one dead reviewer cannot abort the fan-out.
 * @returns { requested, returned, quorum, quorumMet, missing: [{name, reason}], lists }
 *   `lists` holds ONLY the findings of reviewers that genuinely reported, so
 *   synthesis never mixes a silence in with the evidence.
 */
function attestReviewers(settled = []) {
  const attested = (settled ?? []).map((s, i) => {
    const name = String(s?.name ?? `reviewer-${i + 1}`);
    if (s && s.ok === false) return { name, returned: false, reason: cleanReason(s.reason) };
    const value = s ? s.value : undefined;
    if (value === null || value === undefined) return { name, returned: false, reason: REVIEWER_NO_RESULT };
    const findings = Array.isArray(value)
      ? value
      : Array.isArray(value.findings)
        ? value.findings
        : null;
    if (findings === null) return { name, returned: false, reason: REVIEWER_MALFORMED };
    return { name, returned: true, findings };
  });

  const requested = attested.length;
  const returned = attested.filter((a) => a.returned);
  const quorum = reviewerQuorum(requested);
  return {
    requested,
    returned: returned.length,
    quorum,
    // A round that asked for no reviewers (the deterministic gate round) has
    // nothing to attest and is valid on its own terms — quorum gates panels.
    quorumMet: requested === 0 ? true : returned.length >= quorum,
    missing: attested.filter((a) => !a.returned).map((a) => ({ name: a.name, reason: a.reason })),
    lists: returned.map((a) => a.findings),
  };
}

/**
 * The loud line. A reviewer that died environmentally names WHY, because
 * "0 findings" and "nobody looked" must never read the same to a human.
 */
function describeReviewerShortfall(round, attestation) {
  const a = attestation ?? {};
  const why = (a.missing ?? []).length
    ? (a.missing ?? []).map((m) => `${m.name}: ${m.reason}`).join("; ")
    : "no reviewer reported";
  return (
    `Round ${round} INVALID — reviewer quorum not met: ${a.returned ?? 0}/${a.requested ?? 0} reviewers ` +
    `returned (quorum ${a.quorum ?? 0}). Failed reviewers — ${why}. Zero findings from a panel that did not ` +
    `run is absence of evidence, not evidence of absence: this round proves nothing and counts for nothing.`
  );
}

/** The attestation as it rides in the verdict string: `reviewers 2/2 returned`. */
function renderAttestation(attestation) {
  const a = attestation ?? {};
  return `reviewers ${a.returned ?? 0}/${a.requested ?? 0} returned`;
}

// ===== inlined from stopping-rules.mjs (generated; edit stopping-rules.mjs, then rebuild) =====
// Deterministic stopping rules for the convergence loop.
//
// Orchestration-only, like workflow-helpers.mjs: these have no Python oracle, so
// they live outside adjudication.mjs and are inlined into the generated workflow
// separately.
//
// WHY THIS FILE EXISTS (claude-skills#82, this repo #45). Two production runs on
// 2026-09-02/03 showed the loop had no proportional-cost path and no real
// stopping rule:
//   * `pm-816-intake-0903` ran 19 rounds, ~3.5 hours and ~5M tokens on ONE issue
//     and was still surfacing 1-2 genuinely NEW P0s at round 18. Stuck detection
//     never fired because it only matches an IDENTICAL P0/P1 title set, and every
//     round's P0s were different. A human had to halt it; the artifact wanted a
//     SPLIT, not another round.
//   * A separate groom ran 9 rounds at ~11 min and ~273k tokens EACH to drain six
//     WORDING-level P1s, with every lens re-reading the whole artifact each round.
//
// Every rule here is a PURE function over facts the engine already holds. The
// judgment about whether to stop must not live in the LLM that wants to stop —
// the same principle that already governs runLoop's fix-ALL gate and min-rounds
// floor. Agents may supply mechanical measurements (a line count, a diff); they
// never supply the verdict.
//
// Everything fails CLOSED: any missing, malformed, or ambiguous input yields the
// expensive-but-correct answer (a full round), never the cheap one. A wrong
// "eligible" silently costs review quality; a wrong "ineligible" costs one round.

// ---------------------------------------------------------------------------
// Contract lines — what a "low risk" edit may NOT touch
// ---------------------------------------------------------------------------

/** Caps on a delta-eligible fix batch. Both must hold, not either. */
const DELTA_DEFAULTS = { maxChangedLines: 20, maxChangedFraction: 0.05 };

/**
 * Sections whose every line is contract text regardless of content. A wording
 * fix inside a requirements table is not a wording fix — it is a contract edit,
 * and it earns a full round.
 */
const PROTECTED_SECTIONS = [
  "requirement classes",
  "cross-repo design",
  "story points",
  "review receipt",
];

/** `REQ-<CLASS>-<n>` anywhere on the line. */
const REQ_ID = /REQ-[A-Z0-9]+-\d+/;

/**
 * Strip the markdown decoration that precedes a line's actual text, so
 * `* **Acceptance:** …`, `  - Acceptance: …` and `1. Acceptance …` all reduce to
 * text starting with "Acceptance". Ordering matters: quote/list markers can
 * precede emphasis markers and vice versa, so peel repeatedly until stable.
 */
function undecorate(line) {
  let s = String(line ?? "").trim();
  for (;;) {
    const before = s;
    s = s.replace(/^(?:[-*+>]\s*|\d+[.)]\s*|[*_`]+)/, "").trim();
    if (s === before) return s;
  }
}

/** Normalize a heading for comparison: drop leading `#`s, emphasis and case. */
function normalizeSection(section) {
  return undecorate(String(section ?? "").replace(/^#+/, "")).toLowerCase().replace(/\s+/g, " ").trim();
}

/**
 * Is this touched line contract text?
 *
 * @param touched { text, section } — one added-or-removed line as the diff probe
 *   reports it, with `section` = the nearest preceding heading in the artifact.
 * @returns { contract: boolean, kind: string } — `kind` names WHICH rule fired,
 *   so an ineligibility reason can be specific rather than "something matched".
 */
function isContractLine(touched) {
  const text = String(touched?.text ?? "");
  const section = normalizeSection(touched?.section);

  if (PROTECTED_SECTIONS.includes(section)) return { contract: true, kind: `section:${section}` };
  if (REQ_ID.test(text)) return { contract: true, kind: "req-id" };

  const bare = undecorate(text).toLowerCase();
  if (bare.startsWith("acceptance")) return { contract: true, kind: "acceptance" };
  if (bare.startsWith("sto:")) return { contract: true, kind: "sto" };

  return { contract: false, kind: "" };
}

// ---------------------------------------------------------------------------
// Delta eligibility — when a fix batch buys a cheap verifier instead of a round
// ---------------------------------------------------------------------------

/**
 * Decide whether the fix batch just applied was small enough and safe enough
 * that the next round can be a single delta-verifier rather than a full N-lens
 * re-read of the whole artifact.
 *
 * The four predicates are #45's, each computed here rather than judged:
 *   1. the batch fixed ZERO P0 (P1 is allowed only because 2 and 3 bound what a
 *      P1 fix may touch);
 *   2. it changed at most `maxChangedLines` lines AND at most
 *      `maxChangedFraction` of the artifact — both, not either;
 *   3. it touched no contract line (see isContractLine);
 *   4. bookends — round 1 is always full and a delta round never follows another
 *      delta round. That predicate depends on loop position, not on the batch,
 *      so runLoop owns it; this function owns 1 to 3.
 *
 * @param probe { p0FixedCount, artifactLines, touched: [{text, section}], truncated }
 *   as measured by the diff probe. `touched` is EVERY added-or-removed line, so
 *   `changedLines` is its length — one source of truth, no cross-check to drift.
 * @param opts overrides for DELTA_DEFAULTS.
 * @returns { eligible, reason, changedLines } — `reason` is "eligible" or the
 *   name of the first predicate that failed.
 */
function isDeltaEligible(probe, opts = {}) {
  const { maxChangedLines, maxChangedFraction } = { ...DELTA_DEFAULTS, ...opts };

  // A probe that could not enumerate the diff tells us nothing → full round.
  if (!probe || typeof probe !== "object") return { eligible: false, reason: "probe-unavailable", changedLines: null };
  if (probe.truncated === true) return { eligible: false, reason: "size-lines", changedLines: null };
  if (!Array.isArray(probe.touched)) return { eligible: false, reason: "probe-unavailable", changedLines: null };
  const artifactLines = Number(probe.artifactLines);
  if (!Number.isFinite(artifactLines) || artifactLines <= 0) {
    return { eligible: false, reason: "probe-unavailable", changedLines: probe.touched.length };
  }

  const changedLines = probe.touched.length;

  // 1. Severity.
  if (Number(probe.p0FixedCount ?? 0) > 0) return { eligible: false, reason: "p0-in-batch", changedLines };

  // A batch the fixer claims to have applied that changed nothing is a fixer that
  // did not land; that deserves real reviewers, not a confirmation pass.
  if (changedLines === 0) return { eligible: false, reason: "no-diff", changedLines };

  // 2. Size — both caps.
  if (changedLines > maxChangedLines) return { eligible: false, reason: "size-lines", changedLines };
  if (changedLines > artifactLines * maxChangedFraction) {
    return { eligible: false, reason: "size-fraction", changedLines };
  }

  // 3. Contract lines untouched.
  for (const t of probe.touched) {
    const { contract, kind } = isContractLine(t);
    if (contract) return { eligible: false, reason: `contract-line:${kind}`, changedLines };
  }

  return { eligible: true, reason: "eligible", changedLines };
}

// ---------------------------------------------------------------------------
// Divergence — the loop is not approaching a fixed point
// ---------------------------------------------------------------------------

/** Warm-up before the rule may fire, and the comparison window. */
const DIVERGENCE_DEFAULTS = { window: 3, warmup: 6 };

/** Only rounds that actually ran with a reporting reviewer panel are evidence (#81). */
const validRoundsOf = (rounds) => (rounds ?? []).filter((r) => r && r.valid !== false);
const sumNew = (rounds) => rounds.reduce((n, r) => n + Number(r.newP0P1 ?? 0), 0);

/**
 * Is this run diverging rather than converging?
 *
 * Existing stuck detection only fires on an IDENTICAL P0/P1 title set across two
 * rounds, which is why the 19-round run never tripped it: every round's P0s were
 * genuinely new. The signal that DOES describe that run is the arrival rate of
 * new P0/P1 failing to decay.
 *
 * The rule, after `warmup` valid rounds and given `2 * window` of them:
 *   every one of the last `window` rounds surfaced at least one NEW P0/P1, AND
 *   the last `window` rounds surfaced at least as many as the `window` before them.
 * One clean round inside the window, or any decay at all, means the loop is still
 * working and the rule stays silent.
 *
 * INVALID rounds (below reviewer quorum, #81) are skipped entirely: they are
 * neither evidence of divergence nor of decay, so a flaky environment can never
 * fabricate this verdict.
 *
 * @param rounds round reports carrying { newP0P1, valid }.
 * @returns { diverging, reason, validRounds, recentSum, priorSum, window }
 */
function detectDivergence(rounds, opts = {}) {
  const { window, warmup } = { ...DIVERGENCE_DEFAULTS, ...opts };
  const v = validRoundsOf(rounds);
  const base = { diverging: false, reason: "", validRounds: v.length, recentSum: null, priorSum: null, window };

  if (v.length < Math.max(warmup, window * 2)) return base;

  const recent = v.slice(-window);
  const prior = v.slice(-window * 2, -window);
  const recentSum = sumNew(recent);
  const priorSum = sumNew(prior);

  if (!recent.every((r) => Number(r.newP0P1 ?? 0) >= 1)) return { ...base, recentSum, priorSum };
  if (recentSum < priorSum) return { ...base, recentSum, priorSum };

  const span = `${recent[0].round}-${recent[recent.length - 1].round}`;
  const priorSpan = `${prior[0].round}-${prior[prior.length - 1].round}`;
  return {
    diverging: true,
    validRounds: v.length,
    recentSum,
    priorSum,
    window,
    reason:
      `Diverging: rounds ${span} each surfaced a NEW P0/P1 (${recentSum} new, versus ${priorSum} in rounds ` +
      `${priorSpan}) — the finding rate is not decaying, so this loop is not approaching a fixed point. ` +
      `More rounds will not converge it. SPLIT the artifact, re-scope it, or hand it back.`,
  };
}

// ---------------------------------------------------------------------------
// Budget — what the run has actually spent, in the verdict
// ---------------------------------------------------------------------------

/**
 * Roll the round reports into the counts an operator reads in the verdict, so a
 * 19-round run is obvious WHILE it is happening rather than afterwards.
 *
 * `validRounds` — not `roundsRun` — is what the round budget is spent against:
 * a round whose reviewers died is not progress toward an answer (#81).
 */
function summarizeBudget(rounds, opts = {}) {
  const all = rounds ?? [];
  const v = validRoundsOf(all);
  const countKind = (k) => v.filter((r) => (r.kind ?? "full") === k).length;
  return {
    maxRounds: Number(opts.maxRounds ?? 0),
    roundsRun: all.length,
    validRounds: v.length,
    invalidRounds: all.length - v.length,
    fullRounds: countKind("full"),
    deltaRounds: countKind("delta"),
    gateRounds: countKind("gate"),
  };
}

